{"content": """"
索引去重工具 - 为旧条目补算内容指纹、检查并清理重复内容

用法：
  python utils/dedup_index.py            # 补算缺失指纹 + 检查报告（不删除）
  python utils/dedup_index.py --apply    # 检查并删除重复（保留优先条目）
"""

import hashlib
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

INDEX_FILE = Path("minecraft_docs/document_index.json")
BASE_DIR = Path("minecraft_docs")


def normalize(text: str) -> str:
    """与 content_processor 相同的指纹归一化规则"""
    return re.sub(r"\s+", " ", text).strip().lower()


def content_hash(text: str) -> str:
    return hashlib.md5(normalize(text).encode("utf-8")).hexdigest()


def entry_body(entry: dict) -> str:
    """取条目正文（frontmatter 之后的部分）"""
    md = entry.get("files", {}).get("markdown")
    if not md:
        return ""
    p = BASE_DIR / Path(md).relative_to(BASE_DIR)
    if not p.exists():
        return ""
    text = p.read_text(encoding="utf-8")
    # 去掉我们自己的 frontmatter 和标题壳，只比对站点正文
    text = re.sub(r"\A---\s*\n.*?\n---\s*\n", "", text, count=1, flags=re.DOTALL)
    text = re.sub(r"\A#[^\n]*\n+## 内容\n+", "", text, count=1)
    return text


def main(apply: bool = False):
    idx = json.load(open(INDEX_FILE, encoding="utf-8"))
    docs = idx["documents"]

    # 1. 为旧条目补算指纹（正文与已存指纹不一致时以文件正文为准）
    backfilled = 0
    for url, d in docs.items():
        body = entry_body(d)
        if not body:
            continue
        h = content_hash(body)
        if d.get("content_hash") != h:
            d["content_hash"] = h
            backfilled += 1
    print(f"补算/修正指纹: {backfilled} 条")

    # 2. 分组查重
    groups = {}
    for url, d in docs.items():
        h = d.get("content_hash")
        if h:
            groups.setdefault(h, []).append(url)
    dups = {h: urls for h, urls in groups.items() if len(urls) > 1}
    print(f"重复内容组: {len(dups)} 组，涉及 {sum(len(v) for v in dups.values())} 条")

    removed = 0
    for h, urls in dups.items():
        # 保留优先级：中文原语料 > 最早保存的
        keep = min(urls, key=lambda u: (
            0 if docs[u].get("site") == "learn_zh" else 1,
            docs[u].get("saved_at") or "9999",
        ))
        print(f"\n保留: {keep}")
        for u in urls:
            if u == keep:
                continue
            d = docs[u]
            print(f"删除: {u}  [{d.get('site')} | {d.get('title', '')[:40]}]")
            if apply:
                for f in d.get("files", {}).values():
