{"content": """"
近似重复检测 - MinHash/LSH + 5-gram shingle，输出 Jaccard 相似度与包含度报告

用法：
  python utils/find_near_dups.py                # 全量扫描，打印报告 + 存 JSON
  python utils/find_near_dups.py --min-j 0.3    # 调整 Jaccard 阈值（默认 0.30）
"""

import json
import re
import sys
from collections import defaultdict
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
sys.stdout.reconfigure(encoding="utf-8")

INDEX = Path("minecraft_docs/document_index.json")
OUT = Path("minecraft_docs/near_dup_report.json")

TOKEN_RE = re.compile(r"[a-z0-9]+|[\u4e00-\u9fff]")
NGRAM = 5
N_PERM = 64
BANDS = 8  # 8 bands x 8 rows


def tokenize(text: str):
    return TOKEN_RE.findall(text.lower())


def shingles(tokens, n=NGRAM):
    if len(tokens) < n:
        return set()
    return {" ".join(tokens[i:i + n]) for i in range(len(tokens) - n + 1)}


def minhash(sig_sets):
    """sig_sets: {key: np.uint32 array}；乘法哈希 mod 2^64 的 minwise 变体"""
    a = np.random.RandomState(42).randint(1, 2**32, size=N_PERM).astype(np.uint64)
    a |= 1  # 奇数，保证 mod 2^64 下是双射
    keys, sigs = [], []
    for k, hs in sig_sets.items():
        h64 = hs.astype(np.uint64)
        sig = np.empty(N_PERM, dtype=np.uint64)
        for j in range(N_PERM):
            sig[j] = np.min(a[j] * h64)  # numpy 溢出即 mod 2^64
        keys.append(k)
        sigs.append(sig)
    return keys, np.vstack(sigs)


def main(min_j: float = 0.30):
    idx = json.load(open(INDEX, encoding="utf-8"))
    docs = {}
    for url, d in idx["documents"].items():
        jp = d.get("files", {}).get("json")
        if not (jp and Path(jp).exists()):
            continue
        body = json.loads(Path(jp).read_text(encoding="utf-8")).get("markdown_content") or ""
        site = d.get("site") or "learn_zh"
        docs[url] = {"site": site, "title": d.get("title", ""), "body": body}

    print(f"文档数: {len(docs)}，正在构建 shingle…")
    sig_sets = {}
    shingle_sets = {}
    empty = []
    for url, d in docs.items():
        sh = shingles(tokenize(d["body"]))
        if len(sh) < 20:
            empty.append(url)
        shingle_sets[url] = sh
        sig_sets[url] = np.unique(
            np.fromiter((hash(s) & 0xFFFFFFFF for s in sh), dtype=np.uint32)
        ) if sh else np.zeros(1, dtype=np.uint32)

    print("计算 MinHash 签名…")
    keys, sigs = minhash(sig_sets)
    sig_index = {k: i for i, k in enumerate(keys)}

    print("LSH 分桶找候选对…")
    cand = set()
    rows = N_PERM // BANDS
    for b in range(BANDS):
        buckets = defaultdict(list)
        for i, k in enumerate(keys):
            band = sigs[i, b * rows:(b + 1) * rows].tobytes()
            buckets[band].append(k)
        for members in buckets.values():
            if len(members) > 1:
                for x in range(len(members)):
                    for y in range(x + 1, len(members)):
                        cand.add((members[x], members[y]) if members[x] < members[y]
                                 else (members[y], members[x]))

    print(f"候选对: {len(cand)}，精确验证…")
    results = []
    for u1, u2 in cand:
        s1, s2 = shingle_sets[u1], shingle_sets[u2]
        if not s1 or not s2:
            continue
        inter = len(s1 & s2)
        union = len(s1 | s2)
        jac = inter / union
        contain = inter / min(len(s1), len(s2))
        if jac >= min_j or contain >= 0.60:
            results.append({
                "jaccard": round(jac, 3),
                "containment": round(contain, 3),
                "a": {"url": u1, "site": docs[u1]["site"], "title": docs[u1]["title"][:60],
                      "shingles": len(s1)},
                "b": {"url": u2, "site": docs[u2]["site"], "title": docs[u2]["title"][:60],
                      "shingles": len(s2)},
            })

    results.sort(key=lambda r: (-r["jaccard"], -r["containment"]))
    json.dump(results, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)

    print(f"\n命中 {len(results)} 对（Jaccard>={min_j} 或 containment>=0.60），报告: {OUT}\n")
    for r in results[:40]:
        print(f"J={r['jaccard']:.3f} C={r['containment']:.3f} "
              f"[{r['a']['site']}|{r['a']['shingles']}sh] {r['a']['title'][:40]}")
        print(f"        vs [{r['b']['site']}|{r['b']['shingles']}sh] {r['b']['title'][:40]}")


if __name__ == "__main__":
    min_j = 0.30
    for i, a in enumerate(sys.argv):
        if a == "--min-j":
            min_j = float(sys.argv[i + 1])
    main(min_j)
